import{_ as e,c as t,o,ae as i}from"./chunks/framework.Dgg8-8ov.js";const h=JSON.parse('{"title":"About Aalenia","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),n={name:"about.md"};function r(s,a,l,c,d,m){return o(),t("div",null,a[0]||(a[0]=[i('<h1 id="about-aalenia" tabindex="-1">About Aalenia <a class="header-anchor" href="#about-aalenia" aria-label="Permalink to &quot;About Aalenia&quot;">​</a></h1><p>The Aalenian community is the home of the Aalenian Modifications Path of Titans (PoT) modding team and associated PoT community servers. Path of Titans is a massively multiplayer online dinosaur simulation game which allows game owners to host their own &quot;community servers&quot; which can implement game modifications (&quot;mods&quot;) or use third-party applications to customise the play experience. The gaming community typiclly refers to such applications as &quot;bots&quot;.</p><h2 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;Origin&quot;">​</a></h2><p>Aalenia began as a community centered around the develpoment and testing of a JavaScript application for PoT community servers. We sought to create an open-source docker image for servers to deploy locally, to eliminate the issues other bot applications face: latency, downtime, inadequate features, and inadequate customisability.</p><h2 id="mods-and-applications" tabindex="-1">Mods and Applications <a class="header-anchor" href="#mods-and-applications" aria-label="Permalink to &quot;Mods and Applications&quot;">​</a></h2><p>The application developers have moved most application features to the <strong>Aalenian Utilities</strong> mod, though the original application still has some unique functionality and will be available as an open-source project once complete. In addition to this mod, we create a number of mods to improve the community server experience ranging from plant additions to character additions.</p><h2 id="servers" tabindex="-1">Servers <a class="header-anchor" href="#servers" aria-label="Permalink to &quot;Servers&quot;">​</a></h2><p>This community operates a number of PoT community servers to both showcase our mods and applications, and provide a unique dinosaurian experience for players.</p><h2 id="name" tabindex="-1">Name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;Name&quot;">​</a></h2><p>This community is named after the &quot;Aalenian&quot; age, an age of the Middle Jurrasic whose prehistoric context resonates with the content created herein.</p>',10)]))}const p=e(n,[["render",r]]);export{h as __pageData,p as default};
